VAR
    LeadPump : BOOL;
    LagPump : BOOL;
    PumpSetpoint : REAL := 50.0;
    PumpActual : REAL := 0.0;
    PumpMin : REAL := 0.0;
    PumpMax : REAL := 100.0;
    PumpError : REAL;
    PumpOutput : REAL;
    PumpPID : PID;
    PumpStatus : STRUCT
        Mode : STRING := 'Auto';
        Error : REAL := 0.0;
    END_STRUCT;
    WatchdogTimer : TON;
    Heartbeat : BOOL := TRUE;
    LevelHighHigh : BOOL;
    InletValve : BOOL := TRUE;
    MotorOverload : BOOL;
    MotorRun : BOOL := FALSE;
    AutoMode : BOOL := TRUE;
END_VAR
(* Lead Lag Control Logic *)
IF AutoMode THEN
    PumpError := PumpSetpoint - PumpActual;
    PumpOutput := PumpPID(PV := PumpActual, SV := PumpSetpoint);
    PumpOutput := LIMIT(PumpMin, PumpOutput, PumpMax);
    LeadPump := PumpOutput > 0.5;
    IF PumpOutput > 0.7 THEN
        LagPump := TRUE;
    ELSE
        LagPump := FALSE;
    END_IF;
END_IF;
(* Watchdog Timer *)
WatchdogTimer(IN := NOT Heartbeat, PT := T#2s);
IF WatchdogTimer.Q THEN
    LeadPump := FALSE;
    LagPump := FALSE;
END_IF;
(* Inlet Valve Control *)
IF LevelHighHigh THEN
    InletValve := FALSE;
END_IF;
(* Motor Overload Protection *)
IF MotorOverload THEN
    MotorRun := FALSE;
END_IF;
(* Safety Overrides *)
IF LeadPump THEN
    LeadPump := FALSE;
END_IF;
IF LagPump THEN
    LagPump := FALSE;
END_IF;
IF InletValve THEN
    InletValve := FALSE;
END_IF;
IF MotorRun THEN
    MotorRun := FALSE;
END_IF;
END_PROGRAM

