    PumpSetpoint : REAL := 50.0;
    PumpActual : REAL := 0.0;
    PumpMin : REAL := 0.0;
    PumpMax : REAL := 100.0;
    PumpError : REAL;
    PumpOutput : REAL;
    PumpPID : PID;
    PumpSetpointValid : BOOL := TRUE;
    PumpErrorValid : BOOL := TRUE;
    PumpOutputValid : BOOL := TRUE;
    WatchdogTimer : TON;
    Heartbeat : BOOL := TRUE;
    LevelHighHigh : BOOL;
    InletValve : BOOL := TRUE;
    MotorOverload : BOOL;
    MotorRun : BOOL := FALSE;
    AutoMode : BOOL := TRUE;
    PumpStatus : STRUCT
        Enabled : BOOL;
        Fault : BOOL;
        Status : STRING(10);
    END_STRUCT;
END_VAR
(* Validate PumpSetpoint *)
IF NOT (PumpMin <= PumpSetpoint AND PumpSetpoint <= PumpMax) THEN
    PumpSetpointValid := FALSE;
ELSE
    PumpSetpointValid := TRUE;
END_IF;
(* Validate PumpError *)
IF NOT (PumpMin <= PumpError AND PumpError <= PumpMax) THEN
    PumpErrorValid := FALSE;
ELSE
    PumpErrorValid := TRUE;
END_IF;
(* Validate PumpOutput *)
IF NOT (PumpMin <= PumpOutput AND PumpOutput <= PumpMax) THEN
    PumpOutputValid := FALSE;
ELSE
    PumpOutputValid := TRUE;
END_IF;
(* PID Control Logic *)
IF AutoMode THEN
    PumpPID(IN := PumpError, PV := PumpSetpoint, OUT := PumpOutput);
    PumpOutput := LIMIT(PumpMin, PumpOutput, PumpMax);
END_IF;
(* Lead Pump Control *)
IF PumpOutput >= 50.0 THEN
    LeadPump := TRUE;
ELSE
    LeadPump := FALSE;
END_IF;
(* Lag Pump Control *)
IF PumpOutput >= 75.0 THEN
    LagPump := TRUE;
ELSE
    LagPump := FALSE;
END_IF;
(* Watchdog Timer *)
WatchdogTimer(IN := NOT Heartbeat, PT := T#2s);
IF WatchdogTimer.Q THEN
    LeadPump := FALSE;
    LagPump := FALSE;
END_IF;
(* Inlet Valve Control *)
IF LevelHighHigh THEN
    InletValve := FALSE;
END_IF;
(* Motor Overload Control *)
IF MotorOverload THEN
    MotorRun := FALSE;
END_IF;
(* Safety Overrides *)
IF NOT AutoMode THEN
    LeadPump := FALSE;
    LagPump := FALSE;
    InletValve := FALSE;
    MotorRun := FALSE;
END_IF;
END_PROGRAM

