PROGRAM Main
VAR
    Permissive : BOOL;
    SensorA : REAL;
    SensorB : REAL;
    MaxDeviation : REAL := 1.0;
    SensorMismatch : BOOL;
    RawValue : REAL;
    SensorFault : BOOL;
    PowerOK : BOOL;
    MaintenanceMode : BOOL;
    JogCommand : BOOL;
    Actuator1 : BOOL;
    Actuator2 : BOOL;
    Actuator3 : BOOL;
    Setpoint : REAL := 50.0;
    minSetpoint : REAL := 0.0;
    maxSetpoint : REAL := 100.0;
    Mode : INT := 0;
END_VAR
(* Permissive logic *)
Permissive := (SensorA > 0.0) AND (SensorB > 0.0);
(* Sensor mismatch check *)
