        IF AutoMode THEN
            FanSpeed := 50;
            ValvePosition := 30;
            HeaterPower := TRUE;
            SeqStep := 1;
        END_IF;
    1: (* Operation *)
        IF AutoMode THEN
            IF Pressure < LowPressureLimit THEN
                LowPressureAlarm := TRUE;
                ValvePosition := 0;
            ELSE
                LowPressureAlarm := FALSE;
                ValvePosition := 30;
            END_IF;
