PROGRAM Main
VAR
    SeqStep : INT := 0;
    TripA : BOOL := FALSE;
    TripB : BOOL := FALSE;
    TripC : BOOL := FALSE;
    VoteTrip : BOOL;
    Pressure : REAL := 0.0;
    LowPressureLimit : REAL := 10.0;
    LowPressureAlarm : BOOL;
    HighPressureLimit : REAL := 100.0;
    HighPressureAlarm : BOOL;
    MaintenanceMode : BOOL := FALSE;
    Ctl1 : MyBlock;
END_VAR
VoteTrip := (TripA AND TripB) OR (TripA AND TripC) OR (TripB AND TripC);
LowPressureAlarm := Pressure < LowPressureLimit;
HighPressureAlarm := Pressure > HighPressureLimit;
Ctl1(In1 := TRUE);

CASE SeqStep OF
    0 : (* Initial state *)
        IF NOT MaintenanceMode THEN
            Ctl1.Out1 := FALSE;
        END_IF;
    1 : (* Step 1: Check for trip conditions *)
        IF VoteTrip THEN
            Ctl1.Out1 := FALSE;
            SeqStep := 2;
        END_IF;
    2 : (* Step 2: Check pressure limits *)
        IF LowPressureAlarm OR HighPressureAlarm THEN
            Ctl1.Out1 := FALSE;
            SeqStep := 3;
        END_IF;
    3 : (* Step 3: Maintenance mode check *)
        IF MaintenanceMode THEN
            Ctl1.Out1 := FALSE;
            SeqStep := 0;
        END_IF;
END_CASE;

