PROGRAM Main
VAR
    OuterSetpoint : REAL := 100.0;
    OuterPV : REAL := 90.0;
    InnerSetpoint : REAL;
    InnerPV : REAL := 80.0;
    InnerOutput : REAL;
    SensorA : REAL := 75.0;
    SensorB : REAL := 76.0;
    MaxDeviation : REAL := 5.0;
    SensorMismatch : BOOL;
    PowerOK : BOOL := TRUE;
    SensorFault : BOOL;
    RawValue : REAL := 95.0;
    AutoMode : BOOL := TRUE;
    LoopCounter : INT := 0;
    SensorData : ARRAY [0..4] OF REAL := [70.0, 72.0, 74.0, 76.0, 78.0];
END_VAR
    SensorMismatch := ABS(SensorA - SensorB) > MaxDeviation;
    SensorFault := (RawValue < 0.0) OR (RawValue > 100.0);
    IF NOT PowerOK THEN
        InnerOutput := FALSE;
    END_IF;
    IF AutoMode THEN
        InnerSetpoint := LIMIT(50.0, OuterSetpoint, 150.0);
        InnerSetpoint := LIMIT(50.0, InnerSetpoint, 150.0);
        InnerOutput := LIMIT(0.0, InnerSetpoint - InnerPV, 100.0);
        CASE LoopCounter OF
            0: InnerOutput := InnerOutput + 1.0;
            1: InnerOutput := InnerOutput - 1.0;
        END_CASE;
        FOR LoopCounter := 0 TO 4 DO
            SensorData[LoopCounter] := SensorData[LoopCounter] + 0.5;
        END_FOR;
    END_IF;
    IF SensorFault THEN
        InnerOutput := 0.0;
    END_IF;
    (* Safety overrides *)
    IF SensorMismatch THEN
        InnerOutput := 0.0;
    END_IF;
END_PROGRAM

