    LeadPump := FALSE;
    LagPump := FALSE;
    InletValve := FALSE;
    MotorRun := FALSE;
END_IF;
(* Inlet Valve Control *)
IF LevelHighHigh THEN
    InletValve := FALSE;
END_IF;
(* Motor Overload Handling *)
IF MotorOverload THEN
    MotorRun := FALSE;
END_IF;
(* Safety Overrides *)
IF NOT AutoMode THEN
    LeadPump := FALSE;
    LagPump := FALSE;
    InletValve := FALSE;
    MotorRun := FALSE;
END_IF;
