PROGRAM Main
VAR
    Permissive : BOOL;
    SensorA : REAL;
    SensorB : REAL;
    MaxDeviation : REAL := 1.0;
    SensorMismatch : BOOL;
    RawValue : REAL;
    SensorFault : BOOL;
    PowerOK : BOOL;
    MaintenanceMode : BOOL;
    JogCommand : BOOL;
    Actuator1 : BOOL;
    Actuator2 : BOOL;
    Actuator3 : BOOL;
    Setpoint : REAL := 50.0;
    minSetpoint : REAL := 0.0;
    maxSetpoint : REAL := 100.0;
    Mode : INT := 0;
END_VAR
(* Permissive logic *)
Permissive := (SensorA > 0.0) AND (SensorB > 0.0);
(* Sensor mismatch check *)
SensorMismatch := ABS(SensorA - SensorB) > MaxDeviation;
(* Sensor fault check *)
SensorFault := (RawValue < 0.0) OR (RawValue > 100.0);
(* Power OK check *)
IF NOT PowerOK THEN
    Actuator1 := FALSE;
    Actuator2 := FALSE;
    Actuator3 := FALSE;
END_IF;
(* Maintenance mode logic *)
IF MaintenanceMode THEN
    IF JogCommand THEN
        Actuator1 := TRUE;
        Actuator2 := TRUE;
        Actuator3 := TRUE;
    ELSE
        Actuator1 := FALSE;
