PROGRAM Main
VAR
    SeqStep : INT := 0;
    n : INT := 0;
    ShutdownActive : BOOL := FALSE;
    ResetCmd : BOOL := FALSE;
    MotorOverload : BOOL := FALSE;
    MotorRun : BOOL := FALSE;
    Pressure : REAL := 0.0;
    LowPressureLimit : REAL := 10.0;
    LowPressureAlarm : BOOL := FALSE;
    AutoMode : BOOL := TRUE;
    FanSpeed : INT := 0;
    ValvePosition : INT := 0;
    HeaterPower : INT := 0;
END_VAR
(* Sequential control steps *)
CASE SeqStep OF
    0: (* Initialization *)
        IF AutoMode THEN
            FanSpeed := 50;
            ValvePosition := 50;
            HeaterPower := 0;
        END_IF;
        SeqStep := 1;
    1: (* Heating phase *)
        IF AutoMode AND HeaterPower < 100 THEN
            HeaterPower := HeaterPower + 1;
        END_IF;
        IF HeaterPower = 100 THEN
            SeqStep := 2;
        END_IF;
    2: (* Cooling phase *)
        IF AutoMode AND HeaterPower > 0 THEN
            HeaterPower := HeaterPower - 1;
        END_IF;
        IF HeaterPower = 0 THEN
            SeqStep := 0;
        END_IF;
END_CASE;
(* Pressure check *)
LowPressureAlarm := Pressure < LowPressureLimit;
IF LowPressureAlarm THEN
    ValvePosition := 0;
END_IF;
(* Motor overload handling *)
IF MotorOverload THEN
    MotorRun := FALSE;
END_IF;
(* Shutdown logic *)
IF ShutdownActive THEN
    FanSpeed := 0;
    ValvePosition := 0;
    HeaterPower := 0;
    MotorRun := FALSE;
END_IF;
(* Reset command *)
IF ResetCmd AND ShutdownActive THEN
    ShutdownActive := FALSE;
END_IF;
(* Auto mode control *)
IF AutoMode THEN
    (* Fan speed control *)
    IF Pressure < 15.0 THEN
        FanSpeed := 75;
    ELSIF Pressure > 25.0 THEN
        FanSpeed := 25;
    ELSE
        FanSpeed := 50;
    END_IF;
    (* Valve position control *)
    IF Pressure < 15.0 THEN
        ValvePosition := 75;
    ELSIF Pressure > 25.0 THEN
        ValvePosition := 25;
    ELSE
        ValvePosition := 50;
    END_IF;
    (* Heater power control *)
    IF Pressure < 15.0 THEN
        HeaterPower := 100;
    ELSIF Pressure > 25.0 THEN
        HeaterPower := 0;
    ELSE
        HeaterPower := 50;
    END_IF;
END_IF;
(* While loop for counter *)
WHILE n <= 10 DO
    n := n + 1;
END_WHILE;
(* Safety overrides *)
IF ShutdownActive THEN
    FanSpeed := 0;
    ValvePosition := 0;
    HeaterPower := 0;
    MotorRun := FALSE;
END_IF;
END_PROGRAM

